(()=>{
'use strict';
const data=window.GUIDE,model=window.GuideModel,main=document.querySelector('#main'),query=document.querySelector('#query'),searchForm=document.querySelector('#search');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const route=p=>'#'+new URLSearchParams(p).toString();
const link=(p,label,cls='')=>`<a class="${cls}" href="${route(p)}">${esc(label)}</a>`;
function blockTemplate(b){return `<article class="block"><a class="portrait-link" href="${route({species:b.id})}" aria-label="View ${esc(b.name)}"><img class="portrait" src="${esc(b.image)}" alt="${esc(b.name)} artwork" loading="lazy" width="340" height="340"></a><h3>${link({species:b.id},b.name)}</h3><p class="species-description">${esc(b.summary)}</p><div class="block-meta"><span>${esc(b.commonality)}</span><span>${esc(b.size.join(' / '))}</span></div><div class="block-bottom">${link({species:b.id},'View species →')}<a href="${esc(b.infoUrl)}" target="_blank" rel="noopener noreferrer">Extra info ↗</a></div></article>`;}
function listTemplate(blocks){return blocks.map(blockTemplate).join('');}
function detailTemplate(b){const related=b.related.map(id=>data.blocks.find(r=>r.id===id)).filter(Boolean);return `<article class="block block-detail"><img class="portrait" src="${esc(b.image)}" alt="${esc(b.name)} artwork" width="340" height="340"><h1>${esc(b.name)}</h1><p class="species-description detail-summary">${esc(b.summary)}</p><p class="species-description detail-capabilities">${esc(b.capabilities)}</p><p class="detail-link"><a href="${esc(b.infoUrl)}" target="_blank" rel="noopener noreferrer">More about ${esc(b.name)} on D&D Beyond ↗</a></p><section class="species-traits" aria-labelledby="traits-heading"><h2 id="traits-heading">Traits</h2><ul>${b.traits.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section><section class="detail-section tags-section" aria-labelledby="tags-heading"><h2 id="tags-heading">Tags</h2><ul class="tag-list">${[...b.types.map(t=>`<a class="pill" href="${route({view:'type',category:t})}" aria-label="Type: ${esc(t)}">${esc(t)}</a>`),...b.size.map(s=>`<a class="pill" href="${route({view:'size',category:s})}" aria-label="Size: ${esc(s)}">${esc(s)}</a>`),`<a class="pill pill-common" href="${route({common:b.commonality})}" aria-label="Commonality: ${esc(b.commonality)}">${esc(b.commonality)}</a>`].map(t=>`<li>${t}</li>`).join('')}</ul></section><section class="detail-section related-section" aria-labelledby="related-heading"><h2 id="related-heading">Related species</h2><ul class="related-list">${related.map(r=>`<li><a class="related-card" href="${route({species:r.id})}"><img src="${esc(r.image)}" alt="" loading="lazy" width="340" height="340"><span class="related-name">${esc(r.name)}<span class="related-meta">${esc(r.types.join(' / '))}</span></span></a></li>`).join('')}</ul></section></article>`;}
function notes(){return `<div class="notes"><h1>Design notes</h1><section><h2>Tree-test corrections</h2><p>Type is foregrounded. Size and Commonality are grouped with Type so controls are not far apart. Card images support recognition. Search and A–Z sorting support finding species by name.</p><p>Every species has at least one Type. The 30 species in the card sort take each Type that at least 2 of the 6 categorical sorts gave them (AJ’s and Matt’s ranked sorts are excluded). The other 43 were not sorted, so each takes the Types of its closest studied relative, such as Sea Elf from Elf. All 73 blocks are also reachable through Size and search.</p><p>Type, Size, and Commonality allow multiple selections. Species match any selected option within each category and must match every selected category. The boxed X removes one selection. The Commonality filter narrows any view to Popular, Common, Uncommon, or Rare species. Results use one continuous grid, with size and commonality shown after the short description on each card. The Commonality sort runs most common first (↓) and reverses to rarest first (↑) when clicked again; lists can also sort A–Z, and search results by relevance.</p><p>Each species page lists all its tags (Type, Size, Commonality) on one line under the description, then the official details link, then 1–3 related species: the strongest card-sort partners (grouped together in 4+ of 8 sorts) for studied species, otherwise lineage or variant relationships. These live in each record’s <code>related</code> list. Its back link returns to the list view the page was opened from.</p><p>Utility additions: All species, direct detail links, and these notes support navigation and review without changing category membership.</p></section><section><h2>Visual rationale</h2><p>Red base #AC2F2F, tint #F8EAEA, shade #4D1414; deep green #2E6B37 highlights Search, and green #549F54 marks keyboard focus. Official D&D Beyond artwork retains its original colors to help users recognize species; the interface uses the monochromatic red palette, deep green search, and green focus accents.</p><p><strong>Figure–ground:</strong> red Type controls and white cards stand out from the tinted canvas. <strong>Alignment:</strong> shared grid edges and repeated title/metadata positions aid scanning. <strong>Proximity:</strong> Type, Size, and Commonality filters stay together; sorting sits below the sidebar filters and search stays in the results toolbar; each image stays with its name and labels. Rounded cards and consistently shaped rectangular controls distinguish content from navigation.</p><p>Large page titles, medium species names, and small metadata establish type hierarchy.</p></section><section><h2>Shared data and search</h2><p>Cards render GUIDE.blocks through blockTemplate and species pages through detailTemplate. Labels, category membership, related species, and image sources live in data.js.</p><p>Search is available on every page: literal keyword matching, punctuation normalization, synonyms, multiple terms, and one-character name typos. All search runs locally, without AI or external services.</p></section><details><summary>View coverage: ${data.blocks.length} species</summary><div class="table-wrap"><table><thead><tr><th>Species</th><th>Type</th><th>Size</th></tr></thead><tbody>${data.blocks.map(b=>`<tr><td>${link({species:b.id},b.name)}</td><td>${esc(b.types.join(', '))||'Size view only'}</td><td>${esc(b.size.join(', '))}</td></tr>`).join('')}</tbody></table></div></details></div>`;}
// The list view a species page was opened from, so its back link can return there. Kept for the tab's session.
let lastList={hash:'',label:'All species'};
try{lastList=JSON.parse(sessionStorage.getItem('lastList'))||lastList;}catch(e){}
function render(){
 searchForm.remove();
 const raw=location.hash.slice(1),p=new URLSearchParams(raw),q=p.get('q')||'',searching=p.has('q');query.value=q;
 if(raw==='notes'){main.innerHTML=notes();main.prepend(searchForm);document.title='Design notes · D&D Species';return;}
 const b=data.blocks.find(b=>b.id===p.get('species'));
 if(p.has('species')){main.innerHTML=`<div class="detail-toolbar"><nav class="crumb" aria-label="Back">${`<a class="back-link" href="#${esc(lastList.hash)}">${esc(lastList.label)}</a>`}</nav></div>${b?detailTemplate(b):'<h1>Species not found</h1>'}`;main.querySelector('.detail-toolbar').append(searchForm);document.title=(b?b.name:'Species not found')+' · D&D Species';return;}
 const selections=model.readFilters(data,p);
 const activeType=selections.type,activeSize=selections.size,activeCommon=selections.common;
 let blocks=model.filterBlocks(searching?model.search(data.blocks,q):data.blocks,selections);
 // Lists sort A–Z or by commonality (the browse default); search results also by relevance (their default). Commonality runs most common first (desc) or rarest first (asc).
 const sorts=searching?['relevance','az','commonality']:['az','commonality'],sort=sorts.includes(p.get('sort'))?p.get('sort'):(searching?'relevance':'commonality'),dir=p.get('dir')==='asc'?'asc':'desc';
 if(sort==='az')blocks.sort((a,b)=>a.name.localeCompare(b.name));
 if(sort==='commonality'){const d=dir==='asc'?-1:1;blocks.sort((a,b)=>d*(data.commonality.indexOf(b.commonality)-data.commonality.indexOf(a.commonality))||a.name.localeCompare(b.name));}
 const sortParams=sort==='relevance'?{}:{sort,...(sort==='commonality'&&dir==='asc'?{dir}:{})};
 const withParams=(set,drop=[])=>{const n=Object.fromEntries(p);for(const k of drop)delete n[k];return {...n,...set};};
 const filterRoute=(key,values)=>{const next={...selections,[key]:values};return {...(searching?{q}:{}),...Object.fromEntries(Object.entries(next).filter(([,v])=>v.length).map(([k,v])=>[k,v.join(',')])),...sortParams};};
 const filterOption=(key,o,count)=>{const on=selections[key].includes(o),next=on?selections[key].filter(v=>v!==o):[...selections[key],o];return `<div class="filter-option ${on?'selected':''}"><button type="button" class="filter-choice" data-route="${route(filterRoute(key,next))}" aria-pressed="${on}"><span>${esc(o)}</span>${count===undefined?'':`<span class="filter-count">${count}</span>`}</button>${on?`<button type="button" class="filter-remove" data-route="${route(filterRoute(key,next))}" aria-label="Remove ${esc(o)} ${key==='type'?'type':key==='size'?'size':'commonality'} filter"><span aria-hidden="true">×</span></button>`:''}</div>`;};
 const sortRoute=k=>k==='commonality'?withParams({sort:'commonality',dir:sort==='commonality'&&dir==='desc'?'asc':'desc'}):k==='relevance'?withParams({},['sort','dir']):withParams({sort:k},['dir']);
 const arrow=sort==='commonality'&&dir==='asc'?'↑':'↓',commonHint=sort!=='commonality'?'Most common first':dir==='asc'?'Rarest first · click to reverse':'Most common first · click to reverse';
 const sortButton=k=>`<button class="sort-button" type="button" data-route="${route(sortRoute(k))}" aria-pressed="${sort===k}" ${k==='commonality'?`aria-label="Sort by commonality, ${sort===k&&dir==='asc'?'rarest':'most common'} first" title="${commonHint}"`:'aria-label="Sort A to Z"'}>${k==='az'?'A–Z':`Commonality ${arrow}`}</button>`;
 const title=searching?'Search results':activeType.join(' or ')||(activeSize.length?`${activeSize.join(' or ')} species`:activeCommon.length?`${activeCommon.join(' or ')} species`:'All species');
 const subtitle=[activeType.length&&activeSize.length?activeSize.join(' or '):'',activeCommon.length&&(activeType.length||activeSize.length||searching)?activeCommon.join(' or '):''].filter(Boolean).join(' / ');
 const filtered=activeType.length||activeSize.length||activeCommon.length||searching;
 document.title=title+' · D&D Species';
 lastList={hash:raw,label:searching?`Search results for “${q}”`:title+(subtitle?' / '+subtitle:'')};try{sessionStorage.setItem('lastList',JSON.stringify(lastList));}catch(e){}
 main.innerHTML=`<h1 class="sr-only">D&D species</h1><section class="collection"><aside class="sidebar"><nav class="categories" aria-label="Species type"><h2>Type</h2>${link(sortParams,'All species',!filtered?'selected':'')}${data.views[0].options.map(o=>filterOption('type',o,model.browse(data,'type',o).length)).join('')}</nav><nav class="size-nav" aria-label="Size filter"><h2>Size filter</h2><div class="size-pills">${link(filterRoute('size',[]),'All',!activeSize.length?'selected':'')}${data.views[1].options.map(o=>filterOption('size',o)).join('')}</div></nav><nav class="common-nav" aria-label="Commonality filter"><h2>Commonality</h2><div class="size-pills">${link(filterRoute('common',[]),'All',!activeCommon.length?'selected':'')}${data.commonality.slice().reverse().map(o=>filterOption('common',o)).join('')}</div></nav><section class="sort-tools"><h2 id="sort-heading">Sort</h2><div class="sort-control" role="group" aria-labelledby="sort-heading">${['az','commonality'].map(sortButton).join('')}</div></section></aside><div class="results"><div class="results-heading"><div><h2>${esc(title)}${subtitle?` <span class="active-size">/ ${esc(subtitle)}</span>`:''}</h2>${filtered?`<p role="status">${blocks.length} species${searching?` matching “${esc(q)}”`:''}</p>`:''}${filtered?link({},'Clear all ×','clear-link'):''}</div><div class="results-tools"><div id="collection-search"></div></div></div><div class="grid">${listTemplate(blocks)}</div>${!blocks.length?'<div class="empty"><h3>No species found</h3><p>Try a name or keyword, or clear the filters.</p></div>':''}</div></section>`;
 document.querySelector('#collection-search').append(searchForm);
 main.querySelectorAll('[data-route]').forEach(b=>b.addEventListener('click',()=>{location.hash=b.dataset.route;}));
}
 document.querySelector('#search').addEventListener('submit',e=>{e.preventDefault();location.hash=new URLSearchParams({q:query.value.trim()}).toString();});
 window.addEventListener('hashchange',()=>{render();main.focus({preventScroll:true});window.scrollTo(0,0);});render();
})();
